values
('bmlt-labtechniques1-practice-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Which anticoagulant is most commonly used for a complete blood count (CBC)?","translation":"","options":["EDTA","Sodium citrate","Heparin","Sodium fluoride"],"correctIndex":0,"explanation":"EDTA preserves blood cell morphology and is used for CBC. नेपाली: CBC का लागि EDTA भएको tube प्रयोग हुन्छ।","explanationNe":"CBC का लागि EDTA भएको tube प्रयोग हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Which anticoagulant is preferred for routine coagulation tests such as PT and APTT?","translation":"","options":["Sodium citrate","EDTA","Potassium oxalate","Sodium fluoride"],"correctIndex":0,"explanation":"Citrate binds calcium reversibly and is used for coagulation testing. नेपाली: PT/APTT का लागि sodium citrate प्रयोग हुन्छ।","explanationNe":"PT/APTT का लागि sodium citrate प्रयोग हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"Which additive is commonly used in a grey-top tube for plasma glucose estimation?","translation":"","options":["Sodium fluoride with an anticoagulant","EDTA only","Plain clot activator","Sodium citrate only"],"correctIndex":0,"explanation":"Fluoride inhibits glycolysis; grey-top tubes commonly also contain an anticoagulant. नेपाली: Fluoride ले नमुनामा glucose घट्नबाट रोक्छ।","explanationNe":"Fluoride ले नमुनामा glucose घट्नबाट रोक्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Which tube is generally used to collect serum for routine chemistry testing?","translation":"","options":["Plain or clot-activator tube","EDTA tube","Citrate tube","Fluoride tube"],"correctIndex":0,"explanation":"Serum is obtained after blood clots and is centrifuged. नेपाली: Serum लिन plain वा clot-activator tube प्रयोग हुन्छ।","explanationNe":"Serum लिन plain वा clot-activator tube प्रयोग हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"What is the correct order of draw after blood culture bottles in a standard venipuncture sequence?","translation":"","options":["Citrate, serum, heparin, EDTA, fluoride/oxalate","EDTA, citrate, fluoride, serum, heparin","Fluoride, EDTA, serum, citrate, heparin","Serum, fluoride, EDTA, citrate, heparin"],"correctIndex":0,"explanation":"A common order is citrate, serum, heparin, EDTA, then glycolysis inhibitor; follow local standards. नेपाली: गलत order ले additive carryover गराउन सक्छ।","explanationNe":"गलत order ले additive carryover गराउन सक्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"What is the main purpose of centrifugation in sample processing?","translation":"","options":["Separate components based on density","Sterilize the specimen","Destroy all enzymes","Measure pH"],"correctIndex":0,"explanation":"Centrifugation separates cells or precipitates from liquid phases. नेपाली: Centrifuge ले घनत्वका आधारमा घटक छुट्याउँछ।","explanationNe":"Centrifuge ले घनत्वका आधारमा घटक छुट्याउँछ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Which instrument is used to measure absorbance in colorimetric assays?","translation":"","options":["Spectrophotometer","Autoclave","Incubator","Water bath"],"correctIndex":0,"explanation":"A spectrophotometer measures light absorbance at selected wavelengths. नेपाली: Absorbance मापन गर्न spectrophotometer प्रयोग हुन्छ।","explanationNe":"Absorbance मापन गर्न spectrophotometer प्रयोग हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Which principle is used by a colorimeter?","translation":"","options":["Measurement of transmitted/absorbed light through a colored solution","Measurement of electrical resistance only","Measurement of sound waves","Measurement of specimen weight"],"correctIndex":0,"explanation":"Colorimetry estimates concentration from light absorption. नेपाली: रङ्गीन घोलले प्रकाश कति सोस्छ भन्ने मापन गरिन्छ।","explanationNe":"रङ्गीन घोलले प्रकाश कति सोस्छ भन्ने मापन गरिन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Which microscope component controls the amount of light reaching the specimen?","translation":"","options":["Iris diaphragm","Eyepiece","Stage clip","Coarse adjustment knob"],"correctIndex":0,"explanation":"The iris diaphragm regulates illumination and contrast. नेपाली: Iris diaphragm ले प्रकाशको मात्रा नियन्त्रण गर्छ।","explanationNe":"Iris diaphragm ले प्रकाशको मात्रा नियन्त्रण गर्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"Which objective lens is commonly used with immersion oil?","translation":"","options":["100× objective","4× objective","10× objective","40× objective"],"correctIndex":0,"explanation":"The 100× oil-immersion objective improves resolution by reducing refraction. नेपाली: 100× objective सँग immersion oil प्रयोग हुन्छ।","explanationNe":"100× objective सँग immersion oil प्रयोग हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"What is the total magnification with a 10× eyepiece and a 40× objective?","translation":"","options":["400×","40×","100×","4,000×"],"correctIndex":0,"explanation":"Total magnification equals eyepiece magnification multiplied by objective magnification. नेपाली: 10 × 40 = 400 गुणा।","explanationNe":"10 × 40 = 400 गुणा।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"Which microscope adjustment should be used first under low power?","translation":"","options":["Coarse adjustment","Fine adjustment only","Oil immersion","Condenser removal"],"correctIndex":0,"explanation":"Coarse focus is generally used initially at low power, then fine focus. नेपाली: Low power मा सुरुमा coarse adjustment प्रयोग गरिन्छ।","explanationNe":"Low power मा सुरुमा coarse adjustment प्रयोग गरिन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Which device is used to sterilize culture media using saturated steam under pressure?","translation":"","options":["Autoclave","Hot air oven","Refrigerator","Centrifuge"],"correctIndex":0,"explanation":"Autoclaves use pressurized saturated steam for sterilization. नेपाली: Autoclave ले pressure steam बाट sterilize गर्छ।","explanationNe":"Autoclave ले pressure steam बाट sterilize गर्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"Which method is appropriate for sterilizing dry glassware that can tolerate high temperatures?","translation":"","options":["Hot air oven","Membrane filtration","UV lamp only","Pasteurization"],"correctIndex":0,"explanation":"Dry heat in a hot air oven is used for suitable glassware and materials. नेपाली: ताप सहन सक्ने glassware का लागि hot air oven उपयुक्त हुन्छ।","explanationNe":"ताप सहन सक्ने glassware का लागि hot air oven उपयुक्त हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Which sterilization method is suitable for heat-sensitive solutions?","translation":"","options":["Membrane filtration","Autoclaving every solution","Dry heat","Direct flaming"],"correctIndex":0,"explanation":"Filtration removes microorganisms without exposing the solution to heat. नेपाली: Heat-sensitive solution मा membrane filtration प्रयोग गर्न सकिन्छ।","explanationNe":"Heat-sensitive solution मा membrane filtration प्रयोग गर्न सकिन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"What is the purpose of a biological indicator in sterilization monitoring?","translation":"","options":["Verify the effectiveness of the sterilization process using resistant spores","Measure room temperature","Check specimen identity","Measure water hardness"],"correctIndex":0,"explanation":"Biological indicators use resistant spores to challenge the sterilization cycle. नेपाली: Spore indicator ले sterilization प्रभावकारी भयो कि भएन जाँच्छ।","explanationNe":"Spore indicator ले sterilization प्रभावकारी भयो कि भएन जाँच्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"Which indicator is commonly used to monitor autoclave cycles chemically?","translation":"","options":["Autoclave indicator tape or chemical integrator","Urine dipstick","Litmus paper only","Gram stain"],"correctIndex":0,"explanation":"Chemical indicators show exposure to specified process conditions but do not alone prove sterility. नेपाली: Chemical indicator ले cycle का अवस्था पुगेको संकेत गर्छ।","explanationNe":"Chemical indicator ले cycle का अवस्था पुगेको संकेत गर्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"What is the usual purpose of a laboratory refrigerator?","translation":"","options":["Preserve reagents and specimens at controlled low temperature","Sterilize instruments","Incubate bacterial cultures at 37°C","Dry glassware"],"correctIndex":0,"explanation":"Refrigeration slows degradation and microbial growth for suitable materials. नेपाली: Refrigerator ले नमुना/ reagent सुरक्षित राख्न मद्दत गर्छ।","explanationNe":"Refrigerator ले नमुना/ reagent सुरक्षित राख्न मद्दत गर्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"Which device maintains a controlled temperature for microbial culture growth?","translation":"","options":["Incubator","Autoclave","Spectrophotometer","Analytical balance"],"correctIndex":0,"explanation":"An incubator maintains specified conditions for culture growth. नेपाली: Culture बढाउन incubator प्रयोग हुन्छ।","explanationNe":"Culture बढाउन incubator प्रयोग हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"Which balance is appropriate for accurately weighing small quantities of chemicals?","translation":"","options":["Analytical balance","Spring balance","Bathroom scale","Platform trolley scale"],"correctIndex":0,"explanation":"An analytical balance measures small masses with high precision. नेपाली: सानो तौल सही मापन गर्न analytical balance प्रयोग हुन्छ।","explanationNe":"सानो तौल सही मापन गर्न analytical balance प्रयोग हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"What is the main purpose of calibration?","translation":"","options":["Compare an instrument with a traceable standard and adjust/verify its performance","Clean the outside of the instrument only","Increase sample volume","Sterilize the instrument"],"correctIndex":0,"explanation":"Calibration establishes measurement accuracy against a reference standard. नेपाली: Standard सँग तुलना गरी उपकरणको मापन सही छ कि छैन जाँचिन्छ।","explanationNe":"Standard सँग तुलना गरी उपकरणको मापन सही छ कि छैन जाँचिन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"A pipette is used to transfer a measured volume. Which practice improves accuracy?","translation":"","options":["Use the correct pipette range and technique","Use any pipette for every volume","Hold pipette horizontally while aspirating","Reuse disposable tips between patients"],"correctIndex":0,"explanation":"Correct pipette selection, vertical aspiration and consistent technique improve precision. नेपाली: सही range र technique प्रयोग गर्नुपर्छ।","explanationNe":"सही range र technique प्रयोग गर्नुपर्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"What is the purpose of a laboratory reagent blank in spectrophotometry?","translation":"","options":["Correct for absorbance contributed by reagents and solvent","Provide a positive patient result","Replace the calibrator","Measure centrifuge speed"],"correctIndex":0,"explanation":"A reagent blank accounts for background absorbance. नेपाली: Reagent बाट आउने background absorbance हटाउन blank प्रयोग हुन्छ।","explanationNe":"Reagent बाट आउने background absorbance हटाउन blank प्रयोग हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"Which water quality is generally required for preparing many analytical reagents?","translation":"","options":["Purified or deionized water as specified by the method","Untreated river water","Salt water","Any visibly clear water"],"correctIndex":0,"explanation":"Use water quality appropriate to the assay and laboratory SOP. नेपाली: Method अनुसार purified/deionized water चाहिन्छ।","explanationNe":"Method अनुसार purified/deionized water चाहिन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-practice-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"What is the best action when a specimen arrives without a patient identifier?","translation":"","options":["Reject or hold according to specimen acceptance policy and request proper identification","Guess the patient''s identity","Process and report under another patient''s name","Add a label from memory"],"correctIndex":0,"explanation":"Unlabelled specimens require action under strict identification policy; never guess. नेपाली: पहिचान नभएको नमुना अनुमान गरेर report गर्नु हुँदैन।","explanationNe":"पहिचान नभएको नमुना अनुमान गरेर report गर्नु हुँदैन।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"A CBC sample is collected in a sodium citrate tube by mistake. What is the main concern?","translation":"","options":["Incorrect anticoagulant may alter cell counts and sample validity","It is always equivalent to EDTA","It sterilizes the blood","It improves platelet morphology"],"correctIndex":0,"explanation":"CBC requires an appropriate EDTA specimen; wrong tube can invalidate results. नेपाली: CBC का लागि EDTA नमुना चाहिन्छ।","explanationNe":"CBC का लागि EDTA नमुना चाहिन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"A coagulation sample is underfilled in a citrate tube. What is the likely effect?","translation":"","options":["Incorrect blood-to-anticoagulant ratio may prolong clotting results","No effect at all","It increases platelet count accurately","It converts plasma to serum"],"correctIndex":0,"explanation":"Underfilling causes excess citrate relative to plasma and may falsely prolong clotting times. नेपाली: Citrate tube कम भरिँदा PT/APTT गलत बढ्न सक्छ।","explanationNe":"Citrate tube कम भरिँदा PT/APTT गलत बढ्न सक्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"A blood sample for glucose is left unprocessed for several hours at room temperature. What may happen?","translation":"","options":["Glucose may decrease due to glycolysis","Glucose always increases","Potassium becomes zero","Hemoglobin converts to bilirubin"],"correctIndex":0,"explanation":"Cells continue glycolysis after collection unless appropriately controlled. नेपाली: ढिला गर्दा glucose घट्न सक्छ।","explanationNe":"ढिला गर्दा glucose घट्न सक्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"After centrifugation, the serum appears deeply red. This suggests?","translation":"","options":["Hemolysis","Lipemia only","Icterus only","Normal serum"],"correctIndex":0,"explanation":"Red discoloration commonly indicates free hemoglobin from hemolysis. नेपाली: रातो serum hemolysis को संकेत हो।","explanationNe":"रातो serum hemolysis को संकेत हो।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A sample is visibly lipemic. Which analytical issue may occur?","translation":"","options":["Interference in some photometric assays","Guaranteed accurate results","Complete sterilization","No possible interference"],"correctIndex":0,"explanation":"Lipemia can cause turbidity and interfere with some methods. नेपाली: Lipemia ले केही photometric test प्रभावित गर्न सक्छ।","explanationNe":"Lipemia ले केही photometric test प्रभावित गर्न सक्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"A technician uses a 10× eyepiece and a 100× objective. What is the total magnification?","translation":"","options":["1,000×","100×","110×","10,000×"],"correctIndex":0,"explanation":"10 multiplied by 100 equals 1,000. नेपाली: कुल magnification 1000× हुन्छ।","explanationNe":"कुल magnification 1000× हुन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"A technician observes a specimen with a 100× oil-immersion objective. Why is immersion oil used?","translation":"","options":["To reduce light refraction and improve resolution","To stain the specimen","To disinfect the lens","To increase specimen thickness"],"correctIndex":0,"explanation":"Oil improves the optical path between slide and objective. नेपाली: Oil ले प्रकाशको अपवर्तन घटाएर resolution बढाउँछ।","explanationNe":"Oil ले प्रकाशको अपवर्तन घटाएर resolution बढाउँछ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"An autoclave reaches the set temperature but the biological indicator shows growth. What should be concluded?","translation":"","options":["Sterilization failure or inadequate cycle requires investigation","The load is definitely sterile","The indicator can be ignored","Only the tape result matters"],"correctIndex":0,"explanation":"Biological indicator growth indicates the process did not reliably kill the challenge spores. नेपाली: Biological indicator positive भए cycle जाँच गर्नुपर्छ।","explanationNe":"Biological indicator positive भए cycle जाँच गर्नुपर्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"An autoclave indicator tape changes color. What does this prove?","translation":"","options":["The item was exposed to the process conditions indicated by the tape","The item is certainly sterile","All spores were destroyed","The load was free of endotoxin"],"correctIndex":0,"explanation":"Chemical tape indicates exposure, not sterility assurance by itself. नेपाली: Tape ले exposure देखाउँछ, पूर्ण sterility प्रमाणित गर्दैन।","explanationNe":"Tape ले exposure देखाउँछ, पूर्ण sterility प्रमाणित गर्दैन।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"A heat-sensitive antibiotic solution must be sterilized. Which method is most suitable?","translation":"","options":["Membrane filtration using a validated filter","Hot air oven","Direct flame","Dry heat at high temperature"],"correctIndex":0,"explanation":"Filtration is appropriate for heat-labile solutions when validated. नेपाली: तापले बिग्रने solution filtration बाट sterilize गर्न सकिन्छ।","explanationNe":"तापले बिग्रने solution filtration बाट sterilize गर्न सकिन्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A micropipette is set to a volume outside its specified range. What is the likely result?","translation":"","options":["Inaccurate volume delivery and possible instrument damage","Improved precision","Sterilization of sample","No possible effect"],"correctIndex":0,"explanation":"Pipettes must be used within their validated volume range. नेपाली: Pipette को निर्धारित range बाहिर प्रयोग गर्नु हुँदैन।","explanationNe":"Pipette को निर्धारित range बाहिर प्रयोग गर्नु हुँदैन।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
('bmlt-labtechniques1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"A spectrophotometer reading is high even for the reagent blank. What should be checked first?","translation":"","options":["Blank composition, cleanliness of cuvette and instrument baseline","Patient diagnosis only","Incubator humidity","Blood group"],"correctIndex":0,"explanation":"A high blank suggests background contamination, dirty cuvette or baseline issue. नेपाली: Blank र cuvette सफा छ कि जाँच्नुपर्छ।","explanationNe":"Blank र cuvette सफा छ कि जाँच्नुपर्छ।","topic":"Laboratory Techniques, Instruments & Specimen Collection"}'::jsonb,true),
