-- BMLT NHPC: Laboratory Techniques, Instruments & Specimen Collection
-- 25 MCQ Practice + 25 Mock Test; safe to rerun.
begin;
on conflict (content_id) do nothing;
commit;

select content_type,count(*) as total
from public.learning_content
where faculty='BMLT'
and subject='BMLT NHPC Licensing'
and content_data->>'topic'='Laboratory Techniques, Instruments & Specimen Collection'
group by content_type
order by content_type;